"use client";

import { type FocusEvent, type FormEvent, useRef, useState, useSyncExternalStore, useTransition } from "react";
import { Button } from "@/components/ui/button";
import { Field, FieldDescription, FieldError, FieldGroup, FieldLabel } from "@/components/ui/field";
import { Input } from "@/components/ui/input";
import { NativeSelect, NativeSelectOption } from "@/components/ui/native-select";
import {
  type Address,
  type AddressErrors,
  type AddressInput,
  addressSchema,
  checkPostcode,
  EXAMPLE,
  fieldErrors,
  STATES,
} from "@/lib/nigerian-address";

type Props = {
  /** Return field errors to show them, such as a postcode the server refused. */
  onSubmit: (address: Address) => Promise<AddressErrors | void> | AddressErrors | void;
  postcodeRequired?: boolean;
  submitLabel?: string;
};

type Name = keyof AddressInput;

const noop = () => () => {};

export function NigerianAddressForm({ onSubmit, postcodeRequired = false, submitLabel = "Continue" }: Props) {
  const form = useRef<HTMLFormElement>(null);
  const [errors, setErrors] = useState<AddressErrors>({});
  const [suggestion, setSuggestion] = useState<string>();
  const [failed, setFailed] = useState(false);
  const [pending, startTransition] = useTransition();
  // Until React runs, a click would submit the address as a plain GET.
  const ready = useSyncExternalStore(noop, () => true, () => false);

  function show(next: AddressErrors) {
    setErrors(next);
    const first = Object.keys(next)[0];
    if (first) form.current?.querySelector<HTMLElement>(`[name="${first}"]`)?.focus();
  }

  function checkOnBlur(event: FocusEvent<HTMLInputElement>) {
    const input = event.currentTarget;
    const check = input.value.trim() ? checkPostcode(input.value) : undefined;
    if (check?.ok) input.value = check.postcode;
    setSuggestion(check && !check.ok ? check.suggestion : undefined);
    setErrors(({ postcode: _, ...rest }) => (check && !check.ok ? { ...rest, postcode: check.error } : rest));
  }

  function applySuggestion() {
    const input = form.current?.elements.namedItem("postcode");
    if (input instanceof HTMLInputElement && suggestion) input.value = suggestion;
    setSuggestion(undefined);
    setErrors(({ postcode: _, ...rest }) => rest);
  }

  function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setFailed(false);
    const result = addressSchema({ postcodeRequired }).safeParse(
      Object.fromEntries(new FormData(event.currentTarget)),
    );
    if (!result.success) return show(fieldErrors(result.error));
    setErrors({});
    startTransition(async () => {
      try {
        const refused = await onSubmit(result.data);
        if (refused) show(refused);
      } catch {
        setFailed(true);
      }
    });
  }

  function field(name: Name) {
    const error = errors[name];
    return {
      id: name,
      name,
      "aria-invalid": error ? true : undefined,
      "aria-describedby": error ? `${name}-error` : undefined,
    };
  }

  function error(name: Name) {
    return errors[name] && <FieldError id={`${name}-error`}>{errors[name]}</FieldError>;
  }

  return (
    <form ref={form} onSubmit={submit} noValidate aria-busy={pending}>
      <FieldGroup>
        <Field data-invalid={!!errors.name}>
          <FieldLabel htmlFor="name">Full name</FieldLabel>
          <Input {...field("name")} autoComplete="name" />
          {error("name")}
        </Field>
        <Field data-invalid={!!errors.phone}>
          <FieldLabel htmlFor="phone">Phone number</FieldLabel>
          <Input {...field("phone")} type="tel" autoComplete="tel" inputMode="tel" placeholder="0803 123 4567" />
          {error("phone")}
        </Field>
        <Field data-invalid={!!errors.street}>
          <FieldLabel htmlFor="street">Street address</FieldLabel>
          <Input {...field("street")} autoComplete="street-address" />
          {error("street")}
        </Field>
        <Field data-invalid={!!errors.city}>
          <FieldLabel htmlFor="city">Town or city</FieldLabel>
          <Input {...field("city")} autoComplete="address-level2" />
          {error("city")}
        </Field>
        <Field data-invalid={!!errors.lga}>
          <FieldLabel htmlFor="lga">Local government area (optional)</FieldLabel>
          <Input {...field("lga")} />
          {error("lga")}
        </Field>
        <Field data-invalid={!!errors.state}>
          <FieldLabel htmlFor="state">State</FieldLabel>
          <NativeSelect {...field("state")} autoComplete="address-level1" defaultValue="" className="w-full">
            <NativeSelectOption value="" disabled>
              Choose a state
            </NativeSelectOption>
            {STATES.map((state) => (
              <NativeSelectOption key={state} value={state}>
                {state}
              </NativeSelectOption>
            ))}
          </NativeSelect>
          {error("state")}
        </Field>
        <Field data-invalid={!!errors.postcode}>
          <FieldLabel htmlFor="postcode">Postcode{postcodeRequired ? "" : " (optional)"}</FieldLabel>
          <Input
            {...field("postcode")}
            autoComplete="postal-code"
            autoCapitalize="characters"
            autoCorrect="off"
            spellCheck={false}
            maxLength={24}
            placeholder={EXAMPLE}
            onBlur={checkOnBlur}
          />
          <FieldDescription>
            The 11-character NIPOST postcode. Find yours at{" "}
            <a href="https://postcode.gov.ng/find" target="_blank" rel="noreferrer">
              postcode.gov.ng
            </a>
            .
          </FieldDescription>
          {error("postcode")}
          {suggestion && (
            <Button type="button" variant="outline" size="sm" className="w-fit" onClick={applySuggestion}>
              Use {suggestion}
            </Button>
          )}
        </Field>
        {failed && <FieldError>We could not send your address. Try again.</FieldError>}
        <Button type="submit" disabled={!ready || pending}>
          {pending ? "Sending…" : submitLabel}
        </Button>
      </FieldGroup>
    </form>
  );
}

import { InvalidSegment, parse, parseLenient, Postcode, type Segment, WrongLength } from "ng-postcode-js";
import { z } from "zod";

export const STATES = [
  "Abia", "Adamawa", "Akwa Ibom", "Anambra", "Bauchi", "Bayelsa", "Benue", "Borno",
  "Cross River", "Delta", "Ebonyi", "Edo", "Ekiti", "Enugu", "Federal Capital Territory",
  "Gombe", "Imo", "Jigawa", "Kaduna", "Kano", "Katsina", "Kebbi", "Kogi", "Kwara", "Lagos",
  "Nasarawa", "Niger", "Ogun", "Ondo", "Osun", "Oyo", "Plateau", "Rivers", "Sokoto",
  "Taraba", "Yobe", "Zamfara",
] as const;

/** NIPOST's own example code. */
export const EXAMPLE = "FC-02-A09-DB-09";

const SEGMENT_HINTS: Record<Segment, string> = {
  state: "The first two characters must be letters.",
  lga: "Characters 3 and 4 must be digits from 01 to 99.",
  district: "Characters 5 to 7 must be letters or digits.",
  area: "Characters 8 and 9 must be letters.",
  unit: "The last two characters must be digits from 01 to 99.",
};

export type PostcodeCheck =
  | { ok: true; postcode: string }
  | { ok: false; error: string; suggestion?: string };

/** Check a typed postcode and say what is wrong in words a customer understands. */
export function checkPostcode(text: string): PostcodeCheck {
  const code = parse(text);
  if (code instanceof Postcode) return { ok: true, postcode: String(code) };
  if (/^\s*\d{6}\s*$/.test(text)) {
    return { ok: false, error: `That is the old six-digit code. The new postcode looks like ${EXAMPLE}.` };
  }
  const fixed = parseLenient(text);
  if ("postcode" in fixed) {
    return { ok: false, error: "Check your postcode.", suggestion: String(fixed.postcode) };
  }
  if (code instanceof WrongLength) {
    return { ok: false, error: `A postcode has 11 letters and digits, such as ${EXAMPLE}.` };
  }
  if (code instanceof InvalidSegment) return { ok: false, error: SEGMENT_HINTS[code.segment] };
  return { ok: false, error: "Use only letters, digits, spaces and hyphens." };
}

/** A Nigerian mobile number as +234 and ten digits, or null. */
export function normalisePhone(text: string): string | null {
  const match = /^(?:\+?234|0)([789][01]\d{8})$/.exec(text.replace(/[\s().-]/g, ""));
  return match ? `+234${match[1]}` : null;
}

export function addressSchema({ postcodeRequired = false } = {}) {
  return z.object({
    name: z.string().trim().min(2, "Enter your full name.").max(100),
    phone: z
      .string()
      .max(30)
      .transform((value, ctx) => {
        const phone = normalisePhone(value);
        if (phone) return phone;
        ctx.addIssue({ code: "custom", message: "Enter a Nigerian mobile number, such as 0803 123 4567." });
        return z.NEVER;
      }),
    street: z.string().trim().min(3, "Enter your street address.").max(200),
    city: z.string().trim().min(2, "Enter your town or city.").max(100),
    lga: z.string().trim().max(100),
    state: z.enum(STATES, { error: "Choose your state." }),
    postcode: z
      .string()
      .trim()
      .max(40)
      .transform((value, ctx) => {
        if (!value) {
          if (postcodeRequired) ctx.addIssue({ code: "custom", message: "Enter your postcode." });
          return "";
        }
        const check = checkPostcode(value);
        if (check.ok) return check.postcode;
        ctx.addIssue({ code: "custom", message: check.error });
        return z.NEVER;
      }),
  });
}

export type AddressSchema = ReturnType<typeof addressSchema>;
export type AddressInput = z.input<AddressSchema>;
export type Address = z.output<AddressSchema>;
export type AddressErrors = Partial<Record<keyof AddressInput, string>>;

/** The first error for each field. */
export function fieldErrors(error: z.ZodError<AddressInput>): AddressErrors {
  const { fieldErrors } = z.flattenError(error);
  return Object.fromEntries(
    Object.entries(fieldErrors).map(([field, messages]) => [field, messages?.[0]]),
  );
}

import { parse, Postcode } from "ng-postcode-js";
import { ApiError, lookup } from "ng-postcode-js/api";
import { Client, TransportError } from "ng-postcode-js/client";

/**
 * A client for confirming codes, or null without a live key. Test keys answer
 * `not_found` for every code, so they would refuse every order.
 */
export function nipostClient(key = ""): Client | null {
  if (!key.trim()) return null;
  if (/^\s*nipost_(pk_)?test_/.test(key)) {
    console.warn("NG_POSTCODE_API_KEY is a test key, so postcodes are checked offline only.");
    return null;
  }
  // Checkout should not wait long on a third party.
  return new Client(key, { timeoutMs: 3000 });
}

/**
 * Whether NIPOST has assigned the code to a building, or null when it could not say.
 * A level 1 lookup, which uses no credits. Callers should accept the order on null.
 */
export async function isAssigned(postcode: string, client: Client): Promise<boolean | null> {
  const code = parse(postcode);
  if (!(code instanceof Postcode)) return false;
  const found = await client.send(lookup(code, 1));
  if (found instanceof ApiError || found instanceof TransportError) {
    console.warn(`NIPOST lookup failed: ${found}`);
    return null;
  }
  if (found.valid) return true;
  return found.status === "not_found" || found.status === "invalid" ? false : null;
}
